SELECT 
FROM sys_social_app_config a
WHERE a.tenant_id = #{tenantId}
  AND a.connection_id = #{connectionId}
  AND a.del_flag = 0
ORDER BY a.id

SELECT 
FROM sys_social_app_config a
WHERE a.tenant_id = #{tenantId}
  AND a.connection_id = #{connectionId}
  AND a.app_code = #{appCode}
  AND a.del_flag = 0
LIMIT 1
